programs._raw:
{
  "name": "Medicaid for Elders and Adults with Disabilities (EAD)",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "rule": "Countable income must be at or below 100% of the Federal Poverty Level (FPL) for the family size involved.",
      "table": [
        {
          "household_size": 1,
          "monthly_income_limit": 1330,
          "year": 2026
        },
        {
          "household_size": 2,
          "monthly_income_limit": 1803,
          "year": 2026
        }
      ],
      "notes": [
        "Rhode Island’s EAD rules use family size under the FPL methodology.",
        "For people over the standard EAD income limit but with high medical expenses, Rhode Island also has a medically needy pathway under the same broader Medicaid framework."
      ]
    },
    "asset_limits": {
      "individual": 4000,
      "couple": 6000,
      "what_counts": [
        "Countable resources under the SSI methodology"
      ],
      "what_is_exempt": [
        "The available source does not fully enumerate exempt resources in the program text provided; applicants should expect SSI-style exclusions to apply and should verify specific exclusions with DHS."
      ]
    },
    "other_requirements": [
      "Must not be receiving SSI, and must meet the categorical requirements for EAD.",
      "Age 65 or older, or",
      "Be determined disabled by the State Medicaid Assessment and Review Team (MART) under SSI disability standards.",
      "Must meet Rhode Island residency and Medicaid general eligibility rules.",
      "For some pathways, Medicare status is relevant in the application materials, especially for EAD coverage without long-term services and supports."
    ]
  },
  "benefits": {
    "type": "service",
    "value": "Medicaid medical coverage for EAD enrollees, including community Medicaid and, for some applicants, medically needy coverage when income is above 100% FPL but medical expenses are high. The specific service package is not stated as a fixed dollar amount in the sources; it is standard Medicaid coverage rather than a cash benefit.",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online: https://healthyrhode.ri.gov",
      "Phone: 1-855-840-4774 (HealthSource RI)",
      "Phone: 855-697-4347 (Rhode Island DHS)",
      "Paper application through Rhode Island DHS / Health Coverage application packet",
      "In-person through Rhode Island DHS offices"
    ],
    "processing_time": "Not specified in the sources reviewed.",
    "waitlist": "No waitlist is indicated for EAD Medicaid coverage itself. Separate long-term services/supports pathways may have different authorization processes, but EAD community Medicaid is not described as waitlisted.",
    "forms": [
      "Rhode Island Health and Human Services Application for Assistance",
      "Health Coverage application packet for Medicaid, including EAD"
    ],
    "documents": [
      "Proof of age or disability status",
      "Proof of identity",
      "Proof of Rhode Island residency",
      "Income verification",
      "Asset/resource information",
      "Medicare information if applicable",
      "Medical records or disability documentation if disability-based eligibility is being claimed",
      "Information needed for household/family-size determination"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Rhode Island program; no county restrictions were identified.",
    "regional_variations": "No formal regional benefit variation was identified for EAD Medicaid. The main variation is administrative: applicants may work through state DHS/HealthSource RI channels, and local office handling may differ by location.",
    "offices_or_providers": [
      "Rhode Island Department of Human Services (DHS)",
      "HealthSource RI"
    ]
  },
  "official_source": "https://staycovered.ri.gov/your-medicaid-benefits/programs-services/adults-disabilities",
  "gotchas": [
    "The program is often confused with SSI, but EAD is Medicaid coverage with its own eligibility rules; qualifying for SSI automatically qualifies an adult with a disability for Medicaid, but EAD is broader than SSI.",
    "Income over the standard EAD limit does not always end the conversation; Rhode Island’s medically needy pathway may still help if medical expenses are high.",
    "The disability path is not automatic unless the person already receives SSI; MART must determine disability under SSI standards.",
    "Applicants should not assume all assets are counted the same way across Medicaid programs; EAD uses SSI-style resource rules, which can differ from other Medicaid categories.",
    "The application materials reference different routes and hotlines, so families should use the correct channel for the type of case they have."
  ],
  "data_shape_notes": "EAD is a statewide Medicaid eligibility category with two main gates: categorical status (age 65+ or disability) and SSI-style financial rules. Its data structure is unusual because income is tied to FPL household size, resources have fixed dollar caps, and some applicants may instead qualify through a medically needy route if income is too high but medical expenses are significant."
}
